             proto_tree_add_expert(ex_subtree, pinfo, &ei_dhcpv6_non_dns_encoded_name, tvb, offset, 1);
             return;
         }

-        if(!dpos)
+        if(total_label_ascii_len == 0)
             first_lab_off = offset;
-        decoded_name_str[dpos] = '\0';
         offset++;
         remlen--;

